import { Mesh, PlaneGeometry, Object3D, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl?: string, depthMapUrl?: string, meshUrl?: string}} assets
 * @property {string} textContent
 * @property {Array<{name:string, params:any}>} cinematicPrimitives
 * @property {{position:[number,number,number], rotation:[number,number,number], scale:[number,number,number]}} scenePlacement
 * @property {{atlas:number, sourceRect:{x:number,y:number,w:number,h:number}}} atlasRegion
 *
 * @typedef {Object} NodeContext
 * @property {{load: (url:string)=>Promise<THREE.Texture>}} textureLoader
 * @property {{primitives: Record<string, (target:THREE.Object3D, params:any)=>void>}} primitives
 * @property {{fontAtlas: {
 *   createTexture: (text:string, options?:any)=>THREE.Texture
 * }}} fontAtlas
 */

/**
 * Creates a hero‑headline node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ---- Textured image plane -------------------------------------------------
  const { imageUrl } = config.assets || {};
  const imgTex = imageUrl ? ctx.textureLoader.load(imageUrl) : null;

  // Preserve source aspect ratio
  const src = config.atlasRegion?.sourceRect || { w: 1, h: 1 };
  const aspect = src.w / src.h || 1;
  const imgGeom = new PlaneGeometry(aspect, 1, 1, 1);

  const imgMat = new MeshBasicNodeMaterial({
    map: imgTex ? texture(imgTex) : null,
    side: DoubleSide,
    transparent: true,
    depthWrite: false,
  });

  const imgMesh = new Mesh(imgGeom, imgMat);
  imgMesh.position.set(0, 0, 0);

  // ---- Text plane -----------------------------------------------------------
  const txtTex = ctx.fontAtlas.createTexture(config.textContent, {
    // simplistic style – can be extended with design tokens
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 0.13, // scene‑unit based approximation
    fillStyle: '#16161d', // ink
    align: 'center',
    verticalAlign: 'middle',
  });

  const txtGeom = new PlaneGeometry(txtTex.image ? txtTex.image.width / txtTex.image.height : 1, 1);
  const txtMat = new MeshBasicNodeMaterial({
    map: texture(txtTex),
    side: DoubleSide,
    transparent: true,
    depthWrite: false,
  });

  const txtMesh = new Mesh(txtGeom, txtMat);
  // place text slightly in front of the image plane
  txtMesh.position.set(0, -0.6, 0.01);
  txtMesh.scale.set(0.9, 0.9, 1);

  // ---- Root object -----------------------------------------------------------
  const root = new Object3D();
  root.add(imgMesh, txtMesh);

  // Apply placement
  const pos = config.scenePlacement?.position ?? [0, 0, 0];
  const rot = config.scenePlacement?.rotation ?? [0, 0, 0];
  const scl = config.scenePlacement?.scale ?? [1, 1, 1];
  root.position.set(...pos);
  root.rotation.set(...rot);
  root.scale.set(...scl);

  // ---- Cinematic primitives ---------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // ---- User data & cleanup ----------------------------------------------------
  const timelines = [];

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // dispose geometry & material
    imgGeom.dispose();
    imgMat.dispose();
    txtGeom.dispose();
    txtMat.dispose();

    // dispose textures
    if (imgTex) imgTex.dispose();
    if (txtTex) txtTex.dispose();

    // kill any GSAP timelines that might be stored
    timelines.forEach(tl => tl.kill());
  };

  // expose timelines array for potential future animations
  root.userData._timelines = timelines;

  return root;
}
